INTRO = 'At the PS Management office in Madrid, Paquita hosts her annual tarot afternoon with her dear friend and fortune teller María Rosa Cobo. First in the chair is Belinda, eager to ask the cards about a handsome new man in her life. Listen to the Spanish first.'
STORY = [('mariarosa', 'Bueno, Belinda, vamos a tener un renacimiento maravilloso.', 'Well, Belinda, we are going to have a wonderful rebirth.', [(81, 'Bueno, Belinda'), (82, 'vamos a tener un renacimiento maravilloso')], ''), ('mariarosa', 'El día va a terminar fenomenal, con alegría y con suerte.', 'The day is going to end wonderfully, with joy and with luck.', [(83, 'El día va a terminar fenomenal, con alegría'), (84, 'y con suerte')], ''), ('paquita', 'Una vez al año, en la oficina nos reunimos todos los amigos de la casa.', 'Once a year, all the friends of the agency gather here at the office.', [(85, 'Una vez al año, en la oficina'), (86, 'nos reunimos todos los amigos de la casa')], ''), ('paquita', 'Nos reunimos para que María Rosa Cobo nos lea las cartas.', 'We get together so María Rosa Cobo can read our cards.', [(86, 'nos reunimos'), (87, 'para que María Rosa Cobo nos lea las cartas')], ''), ('belinda', '¿Miramos lo del chico ese?', 'Shall we look into that guy?', [(98, '¿Miramos lo del chico ese?')], ''), ('mariarosa', 'Claro que sí, mi vida. Vamos a coger las cartas, que son mágicas.', "Of course, my darling. Let's pick up the cards, because they're magic.", [(98, 'Claro que sí, mi vida'), (99, 'vamos a coger las cartas'), (100, 'que son mágicas')], ''), ('mariarosa', '¿Preparada para lo bueno y lo malo?', 'Ready for the good and the bad?', [(101, '¿Preparada?'), (102, '¿Para lo bueno y lo malo?')], ''), ('belinda', 'Para todo. Desde luego me gusta un montón y hace reír.', 'For everything. I definitely like him a lot and he makes people laugh.', [(102, 'Para todo'), (106, 'gusta un montón'), (110, 'Hace reír')], ''), ('mariarosa', 'Es guapo y es atractivo. Ay, Belinda, es gay. Estoy segurísima.', "He's handsome and attractive. Oh, Belinda, he's gay. I'm completely sure.", [(107, 'Es guapo, es atractivo'), (111, 'Ay, Belinda, es gay'), (113, 'Estoy segurísima')], ''), ('belinda', '¿Y estás segura? La verdad es que es una pasada de hombre.', "And are you sure? Truth is, he's an amazing man.", [(113, '¿Y estás segura?'), (115, 'La verdad es que es una pasada de hombre')], ''), ('paquita', 'Ella sabe mucho de magia. Es la mejor.', "She knows a lot about magic. She's the best.", [(120, 'Ella sabe mucho de magia'), (129, 'Es la mejor')], ''), ('mariarosa', 'Tengo un libro que se titula La magia que hay en ti.', 'I have a book titled The Magic Within You.', [(121, 'Tengo un libro que se titula'), (121, 'La magia que hay en ti')], ''), ('mariarosa', 'Vivir la vida es magia. Todos podemos lograr el éxito en la vida.', 'Living life is magic. All of us can achieve success in life.', [(123, 'Vivir la vida es magia'), (127, 'lograr el éxito en la vida')], ''), ('mariarosa', 'Solamente necesita querer. Y querer es poder, eso está claro, Paquita.', "You only need to want it. And where there's a will there's a way, that's clear, Paquita.", [(128, 'Solamente necesita querer. Y querer es poder, eso está claro, Paquita')], '')]
